public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
    // Initialize a visited array to keep track of the n-tersections that have been visited
    boolean[] visited = new boolean[n];
    // Mark the starting n-tersection as visited
    visited[start[0] * n + start[1]] = true;
    // Initialize a queue to perform Breadth-First Search (BFS)
    Queue<int[]> queue = new LinkedList<>();
    // Add the starting n-tersection to the queue
    queue.add(start);

    while (!queue.isEmpty()) {
        // Get the current n-tersection from the queue
        int[] current = queue.poll();
        // Check if the current n-tersection is the ending n-tersection
        if (current[0] == end[0] && current[1] == end[1]) {
            // If the current n-tersection is the ending n-tersection, return "can be travelled"
            return "can be travelled";
        }
        // Iterate through the paths from the current n-tersection
        for (int i = 0; i < paths.length; i++) {
            // Check if the current path is connected to the current n-tersection
            if (paths[i][0] == current[0] && paths[i][1] == current[1]) {
                // If the current path is connected to the current n-tersection, get the destination n-tersection
                int[] dest = paths[i];
                // Check if the destination n-tersection has already been visited
                if (!visited[dest[0] * n + dest[1]]) {
                    // If the destination n-tersection has not been visited, mark it as visited and add it to the queue
                    visited[dest[0] * n + dest[1]] = true;
                    queue.add(dest);
                }
            }
        }
    }
    // If the queue is empty and the ending n-tersection has not been reached, return "cannot be travelled"
    return "cannot be travelled";
}
