start = pivot;
} else {
end = pivot - 1;
}

// Binary search
while (start <= end) {
int mid = (start + end) / 2;
if (nums[mid] == target) {
return mid;
} else if (nums[mid] < target) {
start = mid + 1;
} else {
end = mid - 1;
}
}

// Target not found
return -1;
